sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber "26V430000" ;
     rc:affects ?v .
  ?v rc:ofModel ?m ;
     rc:modelYear ?year .
  ?m rc:name "TELLURIDE" ;
     rc:ofMake ?mk .
  ?mk rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?categoryName WHERE {
  ?c rc:campaignNumber "10V388000" ;
     rc:affectsComponent ?comp .
  ?comp skos:broader* ?cat .
  FILTER NOT EXISTS { ?cat skos:broader ?parent }
  ?cat rc:name ?categoryName .
}
ORDER BY ?categoryName
